import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"方案介绍","description":"","frontmatter":{},"headers":[],"relativePath":"nex2DevelopmentCases_formPage_dataValidation_masterDetailAmountConstraint_solutionOverview.md","filePath":"nex2DevelopmentCases_formPage_dataValidation_masterDetailAmountConstraint_solutionOverview.md"}'),n={name:"nex2DevelopmentCases_formPage_dataValidation_masterDetailAmountConstraint_solutionOverview.md"};function i(d,t,l,s,h,p){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="方案介绍" tabindex="-1">方案介绍 <a class="header-anchor" href="#方案介绍" aria-label="Permalink to &quot;方案介绍&quot;">​</a></h1><h2 id="方案概述" tabindex="-1">方案概述 <a class="header-anchor" href="#方案概述" aria-label="Permalink to &quot;方案概述&quot;">​</a></h2><p>本方案通过在表单页面（EntityForm）中进行组件级扩展实现。在表单提交前，通过扩展脚本对主表与子表数据进行逻辑校验：一方面校验子表中数量字段是否为空或为 0；另一方面计算子表中所有明细的金额合计，并与主表的总金额字段进行比对，防止提交超出预算上限的数据。若校验不通过，系统将在前端提示用户并阻止表单提交。该方案基于 Nex 页面扩展机制实现，无需调整标准表单结构，即可灵活地在业务层实现主子表约束控制逻辑。</p><h2 id="扩展组件" tabindex="-1">扩展组件 <a class="header-anchor" href="#扩展组件" aria-label="Permalink to &quot;扩展组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终端</th><th>扩展对象</th><th>扩展页面</th><th>扩展区域</th><th>扩展组件</th><th>扩展功能</th></tr></thead><tbody><tr><td>网页端/移动端</td><td>采购申请单</td><td>表单页</td><td>表单底部按钮</td><td>保存按钮</td><td>增加保存前事件，校验主表与子表金额一致性及其他约束规则</td></tr></tbody></table><h2 id="功能设计" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计" aria-label="Permalink to &quot;功能设计&quot;">​</a></h2><ol><li><p><strong>触发时机</strong></p><p>当用户单击“保存”按钮时触发校验逻辑。</p><p>若校验未通过，系统在前端进行提示并阻止保存操作。</p></li><li><p><strong>校验逻辑</strong></p><ul><li><p><strong>子表数据有效性校验</strong></p><p>遍历子表中的每一条明细记录，检查“数量”字段是否为空或等于 0。</p><p>若存在不合法记录，则中止保存流程，并提示用户“采购数量必须是大于0的数字”。</p><p><strong>金额约束校验</strong></p><p>汇总子表中所有明细的“金额”字段求和。</p><p>获取主表的“总金额限制”字段的值。</p><p>若子表金额合计 &gt; 主表总金额限制，则提示用户“子表金额合计超出总金额限制，无法提交”，并终止保存操作。</p></li><li><p><strong>校验通过处理</strong></p><p>若所有校验均通过，则允许保存数据。</p></li></ul></li></ol><h2 id="使用的-nex-扩展能力" tabindex="-1">使用的 NEX 扩展能力 <a class="header-anchor" href="#使用的-nex-扩展能力" aria-label="Permalink to &quot;使用的 NEX 扩展能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能点</th><th>扩展能力类别</th><th>属性/函数/事件</th><th>说明</th><th>示例值/使用方式</th></tr></thead><tbody><tr><td>数据保存前触发数据校验逻辑</td><td>事件绑定</td><td>事件：beforeSave</td><td>定义保存按钮单击后执行保存前的行为逻辑</td><td>beforeSave: (e) =&gt; {/* 校验主子表金额等逻辑 */}</td></tr></tbody></table><h2 id="使用的其他能力" tabindex="-1">使用的其他能力 <a class="header-anchor" href="#使用的其他能力" aria-label="Permalink to &quot;使用的其他能力&quot;">​</a></h2><p>无</p>',11)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
